#define GFS_BASELINE_FIELDS_LIBRARY
#include "test_shared_baseline_fields_v1.cpp"
#include "material_shared_logistic_density.h"
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int ranks;MPI_Comm_size(MPI_COMM_WORLD,&ranks);try{
 need(argc==7&&ranks==1,"packet saved sites weights completed_baseline NEWdest");auto start=std::chrono::steady_clock::now();const auto p=curved::read(argv[1]);const auto f=load_saved(std::string(argv[2])+"/shared_state.bin",p);const auto before=f.coefficient;auto site=sites(argv[3],argv[4]);std::sort(site.begin(),site.end(),[](const Site&a,const Site&b){return a.id<b.id;});std::string old=argv[5],dest=argv[6];
 auto old_axes=read29<RegularAxis>(old+"/regular_axis_proofs_rank0.bin");auto panels=read29<TypedPanel>(old+"/unchanged_baseline_panels_rank0.bin");std::set<uint64_t>failed,passed;std::map<uint64_t,Clearance>selected;
 for(const auto&a:old_axes)if(a.passed)passed.insert(a.slot);else{need(a.panel==0&&a.axis==0&&std::string(a.reason)=="original logistic density poles not excluded on complex domain","only64 first density failures, exact unchanged prefix");need(failed.insert(a.slot).second,"one first failed density record per slot");}
 need(failed.size()==64,"exact64 failed slots");for(auto s:failed)need(!passed.count(s),"no passing full field is replayed");
 for(const auto&b:panels)if(failed.count(b.slot)){auto&w=selected[b.slot].geometry;w.slot=b.slot;w.source=b.source;w.target=b.target;need(b.index==w.panel.size(),"same untouched baseline suffix plan");w.panel.push_back(b);}
 std::map<int,sd::Compiled>maps;std::vector<Clearance*>work;uint64_t count=0;for(auto&e:selected){need(e.second.geometry.panel.size()==88,"same88panel plan for each failed slot");work.push_back(&e.second);count+=e.second.geometry.panel.size();if(!maps.count(e.second.geometry.source))maps.emplace(e.second.geometry.source,sd::compile(f,e.second.geometry.source));}need(count==5632&&work.size()==64,"ONLY unproved11264axes");std::vector<std::vector<SelectedDerivative>>derivatives(work.size());
 #pragma omp parallel for schedule(dynamic,1)
 for(size_t j=0;j<work.size();j++){auto&w=*work[j];try{const auto&m=maps.at(w.geometry.source);std::vector<target::Face>faces;for(const auto&plane:target::planes(site,w.geometry.target))faces.push_back(target::pullback(m,plane));baseline_charts(m,faces,w,derivatives[j]);check(p,m,faces,w,target::stable_complex_density_bound);}catch(const std::exception&e){w.reason=e.what();}
  #pragma omp critical(gfs_density_suffix_progress)
  {fprintf(stderr,"slot=%llu fields=%zu/%zu complete=%d reason=%s\n",(unsigned long long)w.geometry.slot,w.fields.size(),2*w.geometry.panel.size(),w.complete,w.reason.c_str());fflush(stderr);}
 }
 std::vector<RegularAxis>axes;std::vector<FullField>fields;std::vector<pr::Boundary>boundaries;std::vector<TypedPanel>unchanged;std::vector<SelectedDerivative>proof;uint64_t complete=0;
 std::ofstream csv(dest+"/regular_geometry_density_clearance.csv");csv<<"slot_id,source,target,regular_panels,checked_axes,passed_axes,clearance_complete,cached_boundary_records,reason\n";
 for(size_t j=0;j<work.size();j++){const auto&w=*work[j];append(axes,w.axes);append(fields,w.fields);append(boundaries,w.boundaries);append(unchanged,w.geometry.panel);append(proof,derivatives[j]);complete+=w.complete;csv<<w.geometry.slot<<','<<w.geometry.source<<','<<w.geometry.target<<','<<w.geometry.panel.size()<<','<<w.axes.size()<<','<<w.fields.size()<<','<<w.complete<<','<<w.boundaries.size()<<','<<w.reason<<'\n';}csv.close();
 packet(dest+"/regular_axis_proofs_rank0.bin",axes,0);packet(dest+"/passed_regular_full_fields_rank0.bin",fields,0);packet(dest+"/prepared_regular_boundaries_rank0.bin",boundaries,0);packet(dest+"/unchanged_baseline_panels_rank0.bin",unchanged,0);packet(dest+"/selected_derivative_proofs_rank0.bin",proof,0);
 need(!memcmp(before.data(),f.coefficient.data(),before.size()*sizeof(STCoefficient)),"equivalent density proof preserves physical state/heat");
 printf("{\"scope\":\"only64previously failed slots/5632unchanged panels; same density with two-sided logistic disk, no successful field replay\",\"regular_panels\":5632,\"slot_jobs\":64,\"completed_regular_slot_clearances\":%llu,\"new_complex_axis_evaluations\":%zu,\"new_complex_axis_passes\":%zu,\"saved_full_fields\":%zu,\"cached_boundary_records\":%zu,\"selected_derivative_records\":%zu,\"previous_successful_field_replays\":0,\"new_arrangements\":0,\"new_event_root_jobs\":0,\"new_inverse_solves\":0,\"new_physical_quadrature_queries\":0,\"density_profile_changed\":false,\"all12_analytic_remainders_complete\":false,\"full_quadrature_allowed\":false,\"state_unchanged\":true,\"OMP_threads\":%d,\"seconds\":%.17g}\n",(unsigned long long)complete,axes.size(),fields.size(),fields.size(),boundaries.size(),proof.size(),omp_get_max_threads(),std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count());
 }catch(const std::exception&e){fprintf(stderr,"density suffix FAIL %s\n",e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return 0;}
